:root { --bg: #f7f7f8; --panel: #ffffff; --border: #e5e7eb; --text: #111827; --muted: #6b7280; --accent: #2563eb; --accent-hover: #1d4ed8; --user-bubble: #2563eb; --user-text: #ffffff; --assistant-bubble: #f3f4f6; --assistant-text: #111827; --error: #b91c1c; --shadow: 0 10px 30px rgba(15, 23, 42, 0.08); }@media (prefers-color-scheme: dark) {
  :root { --bg: #0b0f17; --panel: #111827; --border: #1f2937; --text: #f9fafb; --muted: #9ca3af; --assistant-bubble: #1f2937; --assistant-text: #f9fafb; --shadow: 0 10px 30px rgba(0, 0, 0, 0.4); }
}* { box-sizing: border-box; }html, body { height: 100%; }body { margin: 0px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; background: var(--bg); color: var(--text); display: flex; align-items: center; justify-content: center; padding: 24px; }.shell { width: 100%; max-width: 760px; height: min(820px, -48px + 100vh); background: var(--panel); border: 1px solid var(--border); border-radius: 16px; box-shadow: var(--shadow); display: flex; flex-direction: column; overflow: hidden; }header { padding: 16px 20px; border-bottom: 1px solid var(--border); display: flex; align-items: center; gap: 12px; }.avatar { width: 36px; height: 36px; border-radius: 50%; background: linear-gradient(135deg, rgb(99, 102, 241), rgb(37, 99, 235)); color: rgb(255, 255, 255); display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 14px; flex-shrink: 0; }.title { font-weight: 600; font-size: 15px; }.subtitle { color: var(--muted); font-size: 12px; margin-top: 2px; }.header-meta { flex: 1 1 0%; min-width: 0px; }.header-actions { display: flex; gap: 8px; }.icon-btn { background: transparent; border: 1px solid var(--border); color: var(--text); width: 34px; height: 34px; border-radius: 8px; cursor: pointer; font-size: 16px; display: flex; align-items: center; justify-content: center; }.icon-btn:hover { background: var(--bg); }.settings { border-bottom: 1px solid var(--border); padding: 14px 20px; background: var(--bg); display: none; gap: 10px; flex-direction: column; }.settings.open { display: flex; }.settings label { font-size: 12px; color: var(--muted); display: flex; flex-direction: column; gap: 4px; }.settings input, .settings textarea, .settings select { padding: 8px 10px; border-radius: 8px; border: 1px solid var(--border); background: var(--panel); color: var(--text); font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: 13px; }.settings textarea { resize: vertical; min-height: 60px; }.settings .row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }@media (max-width: 560px) {
  .settings .row { grid-template-columns: 1fr; }
}.messages { flex: 1 1 0%; overflow-y: auto; padding: 20px; display: flex; flex-direction: column; gap: 12px; }.empty { margin: auto; text-align: center; color: var(--muted); font-size: 14px; max-width: 360px; }.empty h2 { color: var(--text); font-size: 18px; margin: 0px 0px 6px; }.row-msg { display: flex; gap: 10px; align-items: flex-end; }.row-msg.user { justify-content: flex-end; }.row-msg .avatar-sm { width: 28px; height: 28px; border-radius: 50%; flex-shrink: 0; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; color: rgb(255, 255, 255); }.row-msg.assistant .avatar-sm { background: linear-gradient(135deg, rgb(99, 102, 241), rgb(37, 99, 235)); }.row-msg.user .avatar-sm { background: rgb(75, 85, 99); order: 2; }.bubble { padding: 10px 14px; border-radius: 14px; max-width: 78%; white-space: pre-wrap; overflow-wrap: break-word; line-height: 1.45; font-size: 14px; }.row-msg.user .bubble { background: var(--user-bubble); color: var(--user-text); border-bottom-right-radius: 4px; }.row-msg.assistant .bubble { background: var(--assistant-bubble); color: var(--assistant-text); border-bottom-left-radius: 4px; }.bubble.error { background: rgb(254, 226, 226); color: var(--error); }.tool-error { padding: 8px 10px; border-radius: 8px; background: rgb(254, 226, 226); color: var(--error); font-size: 13px; line-height: 1.4; display: flex; flex-direction: column; gap: 6px; }.tool-error-meta { font-size: 11px; opacity: 0.85; }.retry-btn { align-self: flex-start; padding: 4px 10px; border: 1px solid; border-radius: 999px; background: transparent; color: inherit; font-size: 12px; cursor: pointer; }.retry-btn:hover { background: rgba(220, 38, 38, 0.08); }.retry-btn:disabled { opacity: 0.5; cursor: progress; }.cursor::after { content: "▍"; display: inline-block; margin-left: 1px; animation: 1s steps(2) 0s infinite normal none running blink; color: var(--muted); }@keyframes blink { 
  50% { opacity: 0; }
}.typing { display: inline-flex; gap: 3px; align-items: center; padding: 4px 0px; }.typing span { width: 6px; height: 6px; border-radius: 50%; background: var(--muted); animation: 1.2s ease-in-out 0s infinite normal none running bounce; }.typing span:nth-child(2) { animation-delay: 0.15s; }.typing span:nth-child(3) { animation-delay: 0.3s; }@keyframes bounce { 
  0%, 60%, 100% { transform: translateY(0px); opacity: 0.4; }
  30% { transform: translateY(-4px); opacity: 1; }
}.composer { border-top: 1px solid var(--border); padding: 14px 20px; display: flex; gap: 10px; align-items: flex-end; background: var(--panel); }.composer textarea { flex: 1 1 0%; resize: none; padding: 10px 12px; border-radius: 10px; border: 1px solid var(--border); background: var(--bg); color: var(--text); font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: 14px; max-height: 140px; min-height: 40px; line-height: 1.4; }.composer textarea:focus { outline: 2px solid var(--accent); outline-offset: -1px; }.send-btn { background: var(--accent); color: rgb(255, 255, 255); border: 0px; border-radius: 10px; padding: 10px 16px; font-size: 14px; font-weight: 600; cursor: pointer; flex-shrink: 0; }.send-btn:hover:not(:disabled) { background: var(--accent-hover); }.send-btn:disabled { opacity: 0.5; cursor: not-allowed; }.status { padding: 6px 20px; font-size: 11px; color: var(--muted); border-top: 1px solid var(--border); background: var(--bg); display: flex; justify-content: space-between; gap: 12px; }.status .dot { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: rgb(156, 163, 175); margin-right: 4px; vertical-align: middle; }.status .dot.live { background: rgb(16, 185, 129); }.empty { margin: auto; text-align: center; color: var(--muted); font-size: 14px; max-width: 560px; padding: 8px 20px 16px; animation: 0.7s cubic-bezier(0.2, 0.7, 0.2, 1) 0s 1 normal none running hero-in; }@keyframes hero-in { 
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0px); }
}.hero-orb { position: relative; width: 88px; height: 88px; margin: 0px auto 22px; }.hero-orb .orb-core { position: absolute; inset: 18px; border-radius: 50%; background: conic-gradient(rgb(99, 102, 241), rgb(139, 92, 246), rgb(236, 72, 153), rgb(245, 158, 11), rgb(6, 182, 212), rgb(99, 102, 241)); box-shadow: rgba(99, 102, 241, 0.45) 0px 12px 32px, rgba(255, 255, 255, 0.35) 0px 0px 18px inset; animation: 9s linear 0s infinite normal none running orb-spin; }.hero-orb .orb-core::after { content: ""; position: absolute; inset: 18%; border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.9), rgba(255, 255, 255, 0) 55%); }.hero-orb .orb-ring { position: absolute; inset: 0px; border-radius: 50%; border: 1.5px solid rgba(99, 102, 241, 0.45); animation: 2.6s ease-out 0s infinite normal none running orb-pulse; }.hero-orb .orb-ring-2 { animation-delay: 1.3s; border-color: rgba(236, 72, 153, 0.45); }@keyframes orb-spin { 
  100% { transform: rotate(360deg); }
}@keyframes orb-pulse { 
  0% { transform: scale(0.85); opacity: 0.85; }
  100% { transform: scale(1.7); opacity: 0; }
}.hero-title { font-size: 28px; font-weight: 700; margin: 0px 0px 10px; letter-spacing: -0.01em; background: linear-gradient(90deg, rgb(99, 102, 241), rgb(139, 92, 246), rgb(236, 72, 153), rgb(245, 158, 11), rgb(99, 102, 241)) 0% 0% / 200% 100% text; color: transparent; animation: 6s linear 0s infinite normal none running hero-shimmer; }@keyframes hero-shimmer { 
  100% { background-position: 200% 50%; }
}.hero-sub { font-size: 14px; color: var(--muted); line-height: 1.55; margin: 0px auto 22px; max-width: 460px; }.hero-sub code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12.5px; background: linear-gradient(135deg, rgba(99, 102, 241, 0.14), rgba(236, 72, 153, 0.14)); padding: 1px 6px; border-radius: 5px; color: rgb(219, 39, 119); }@media (prefers-color-scheme: dark) {
  .hero-sub code { color: rgb(249, 168, 212); }
}.hero-pills { display: inline-flex; flex-wrap: wrap; justify-content: center; gap: 6px; margin-bottom: 26px; }.hero-pill { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border: 1px solid var(--border); border-radius: 999px; font-size: 11.5px; color: var(--muted); background: var(--bg); }.pill-dot { width: 6px; height: 6px; border-radius: 50%; background: rgb(99, 102, 241); animation: 2.2s ease-in-out 0s infinite normal none running pill-blink; }.pill-dot-2 { background: rgb(236, 72, 153); animation-delay: 0.5s; }.pill-dot-3 { background: rgb(16, 185, 129); animation-delay: 1s; }@keyframes pill-blink { 
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}.suggestions { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; text-align: left; }@media (max-width: 520px) {
  .suggestions { grid-template-columns: 1fr; }
}.suggestion { display: flex; align-items: center; gap: 12px; padding: 12px 14px; background: var(--panel); border: 1px solid var(--border); border-radius: 12px; cursor: pointer; text-align: left; font: inherit; color: var(--text); transition: transform 0.2s, border-color 0.2s, box-shadow 0.2s; }.suggestion:hover { transform: translateY(-2px); border-color: rgba(99, 102, 241, 0.55); box-shadow: rgba(99, 102, 241, 0.45) 0px 10px 22px -12px; }.suggestion-icon { flex-shrink: 0; width: 34px; height: 34px; display: inline-flex; align-items: center; justify-content: center; background: linear-gradient(135deg, rgba(99, 102, 241, 0.14), rgba(236, 72, 153, 0.14)); border-radius: 9px; color: rgb(99, 102, 241); }@media (prefers-color-scheme: dark) {
  .suggestion-icon { color: rgb(165, 180, 252); }
}.suggestion-text { display: flex; flex-direction: column; gap: 2px; font-size: 13px; min-width: 0px; }.suggestion-text strong { color: var(--text); font-weight: 600; }.suggestion-text span { color: var(--muted); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

